#!/usr/bin/env python3
from pathlib import Path
import json,hashlib
import pandas as pd
ROOT=Path('/home/ubuntu/CHAOS'); SRC=ROOT/'campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH'; OBS=ROOT/'experiments/multi_domain_native_adapters_v1/imf_imts_v2/IMF_IMTS_XG_OBSERVED_RECORDS_2000_2024.csv'; PROFILE=json.loads((SRC/'IMF_IMTS_REPORTER_UNIVERSE_COVERAGE_PROFILE_V2.json').read_text()); CODE=json.loads((SRC/'IMF_IMTS_CODELISTS_V1.json').read_text()); OUT=ROOT/'experiments/multi_domain_native_edges_v2/imf_partner_dependence_v2'; OUT.mkdir(parents=True,exist_ok=True); reporters=PROFILE['wdi_target_ready_ids']; terms=['world','not specified','unspecified','special categories','countries & areas','other countries','all countries','regional aggregate','region','group','union','area not elsewhere included','oil related aggregate','services aggregate']; names={x['id']:(x.get('names',{}).get('en') or x.get('name') or x['id']) for c in CODE['codelists'] if c['id']=='CL_IMTS_COUNTRY' for x in c['codes']}; d=pd.read_csv(OBS,low_memory=False); d=d[(d.country.isin(reporters))&(d.indicator=='XG_FOB_USD')&(d.frequency=='A')].copy(); d['year']=pd.to_numeric(d.time_period,errors='coerce'); d['value']=pd.to_numeric(d.obs_value_raw,errors='coerce'); d=d.dropna(subset=['country','counterpart_country','year','value']); d=d.drop_duplicates(['country','counterpart_country','year']); world=d[d.counterpart_country=='G001'][['country','year','value']].rename(columns={'country':'reporter_id','value':'world_exports_raw'}); world=world.drop_duplicates(['reporter_id','year']); bil=d[d.counterpart_country!='G001'].copy(); bil['partner_name']=bil.counterpart_country.map(names).fillna(bil.counterpart_country); bil=bil[~bil.apply(lambda r: str(r.counterpart_country)==str(r.country) or any(t in f"{r.counterpart_country} {r.partner_name}".lower() for t in terms),axis=1)].copy(); rows=[]; cov=[]
