  v=g.set_index('year').value; yrs=[y for y in range(2000,2005) if y in v.index and y in w.index and pd.notna(v.loc[y]) and pd.notna(w.loc[y]) and v.loc[y]>0 and w.loc[y]>0]
  if len(yrs)==5:
   shares={str(int(y)):float(v.loc[y]/w.loc[y]) for y in yrs}; candidates.append({'reporter_id':rep,'partner_id':pid,'partner_name':pname,'baseline_years':5,'baseline_mean_share':float(sum(shares.values())/5),'baseline_shares':json.dumps(shares,sort_keys=True)})
