(OUT/'IMF_IMTS_PARTNER_EXCLUSION_REGISTER_V2.json').write_text(json.dumps({'source':'CL_IMTS_COUNTRY','reporters':reporters,'rules':terms,'rows':exclusions,'count':len(exclusions)},ensure_ascii=False,indent=2)+'\n'); summ={'test_id':'IMF_IMTS_PARTNER_SELECTION_V2','contract_id':'IMF_IMTS_PARTNER_DEPENDENCE_CONTRACT_V2','input_sha256':hashlib.sha256(OBS.read_bytes()).hexdigest(),'reporter_universe_count':len(reporters),'reporters_with_complete_candidate_pool':int(covdf.selection_complete.sum()),'reporters_with_five_active':int((covdf.active_set_size==5).sum()),'selection_rows':int(len(selection)),'candidate_pool_size':10,'active_set_size':5,'coverage':cov,'status':'profile_complete'}; (OUT/'IMF_IMTS_PARTNER_SELECTION_SUMMARY_V2.json').write_text(json.dumps(summ,ensure_ascii=False,indent=2)+'\n'); print(json.dumps({'reporter_universe':len(reporters),'complete_candidate_pool':summ['reporters_with_complete_candidate_pool'],'five_active':summ['reporters_with_five_active'],'selection_rows':len(selection),'top3_50_count':int(covdf.top3_share_50pct.sum()),'top1_20_count':int(covdf.top1_share_20pct.sum()),'top5_70_count':int(covdf.top5_share_70pct.sum())},ensure_ascii=False,indent=2))
